fn is_prime(n: i8) -> bool {
    // Numbers less than 2 are not prime
    if n < 2 {
        return false;
    }
    
    // Handle negative numbers (though i8 < 2 already covers negatives)
    if n < 0 {
        return false;
    }
    
    // Check divisors from 2 up to sqrt(n) (optimization)
    // For i8, we can check up to n-1 as specified, but sqrt is more efficient
    let limit = (n as f64).sqrt() as i8 + 1;
    
    for d in 2..=limit {
        if n % d == 0 {
            return false;
        }
    }
    
    true
}